cat > scripts/readme-facts.ts <<'EOF'
import { readFileSync, writeFileSync } from "node:fs";

const START = "<!-- facts:start -->";
const END = "<!-- facts:end -->";

function lookup(facts: string, key: string): string {
  for (const line of facts.split("\n")) {
    const m = line.match(/^([A-Z0-9_]+) = (.*?)(?:\s+\(source:.*)?$/);
    if (!m || m[1] !== key) continue;
    const value = m[2].trim();
    return value === "" || value === "PENDING" ? "pending" : value;
  }
  return "pending";
}

export function renderResults(readme: string, facts: string, keys: string[]): string {
  const s = readme.indexOf(START);
  if (s < 0) return readme;
  const bodyStart = s + START.length;
  const e = readme.indexOf(END, bodyStart);
  if (e < 0) return readme;
  const bullets = keys.map((k) => `- ${k}: ${lookup(facts, k)}`).join("\n");
  return `${readme.slice(0, bodyStart)}\n${bullets}\n${readme.slice(e)}`;
}

if (import.meta.main) {
  const [readmePath = "README.md", factsPath = "docs/FACTS.md", ...keys] = process.argv.slice(2);
  const readme = readFileSync(readmePath, "utf8");
  writeFileSync(readmePath, renderResults(readme, readFileSync(factsPath, "utf8"), keys));
}
EOF
cat > tests/readme-facts.test.ts <<'EOF'
import { expect, test } from "bun:test";
import { renderResults } from "../scripts/readme-facts";

const facts = [
  "# Facts",
  "A = 4.23, rounded to 2 decimals  (source: x.json#$.a, generated now)",
  "B = PENDING  (source: y.json#$.b, generated now)",
].join("\n");
const readme = "intro\n<!-- facts:start -->\nold 99\n<!-- facts:end -->\noutro\n";

test("renders bullets, pending for PENDING and missing", () => {
  const out = renderResults(readme, facts, ["A", "B", "C"]);
  expect(out).toBe(
    "intro\n<!-- facts:start -->\n- A: 4.23, rounded to 2 decimals\n- B: pending\n- C: pending\n<!-- facts:end -->\noutro\n",
  );
  expect(out).not.toContain("old 99");
});

test("markers absent returns unchanged", () => {
  expect(renderResults("no markers", facts, ["A"])).toBe("no markers");
});

test("idempotent", () => {
  const once = renderResults(readme, facts, ["A", "B"]);
  expect(renderResults(once, facts, ["A", "B"])).toBe(once);
});
EOF
bun test tests/readme-facts.test.ts 2>&1 | tail -8; bun run typecheck 2>&1 | tail -5; bun test 2>&1 | tail -5

